import pandas as pd, numpy as np
r = pd.read_csv("data/ratings.csv.gz", parse_dates=["rated_at"], dtype={"rating_id": str})
r = r.sort_values("rating_id").reset_index(drop=True)
s = pd.read_csv("reference/feature_sample.csv", dtype={"rating_id": str})
s = s.merge(r[["rating_id","member_id","rated_at"]], on="rating_id")
def gapf(ts, sec):
    return float(np.round(np.float32((ts - pd.Timestamp(sec)).total_seconds())/86400.0, 6))
NO_PREV = float(np.round(np.float32(pd.Timestamp.min.value)/86400.0, 6))
TOL=1e-9
def score(fn):
    ok=0
    for _, row in s.iterrows():
        m=row.member_id; ts=pd.Timestamp(row.rated_at); ref=row.f_mbr_days_since_prev
        sub=r[r.member_id==m]
        exp=fn(sub, ts)
        if abs(exp-ref)<TOL: ok+=1
    return ok

def h_last_distinct(sub, ts):
    st=sub[sub.rated_at<ts]
    if not len(st): return NO_PREV
    return gapf(ts, st.rated_at.max())
def h_second_last_distinct(sub, ts):
    st=sub[sub.rated_at<ts]
    u=np.unique(st.rated_at.values)
    if len(u)==0: return NO_PREV
    if len(u)==1: return gapf(ts, u[-1])
    return gapf(ts, u[-2])
def h_prev_rating_id(sub, ts, rid):
    i=sub.index[sub.rating_id==rid][0]
    if i==0: return NO_PREV
    return gapf(ts, sub.rated_at.iloc[i-1])

print("last distinct:", score(h_last_distinct))
print("second-last distinct:", score(h_second_last_distinct))
EOF"}
